def _poly_trim(p):
    p=list(p)
    while len(p)>1 and p[-1]==0:
        p.pop()
    return p

def _poly_der(p):
    return [F(i)*p[i] for i in range(1,len(p))] or [F(0)]

def _poly_divrem(a,b):
    a=_poly_trim(a); b=_poly_trim(b); r=a[:]
    q=[F(0)]*max(1,len(a)-len(b)+1)
    while len(r)>=len(b) and not (len(r)==1 and r[0]==0):
        c=r[-1]/b[-1]; d=len(r)-len(b); q[d]+=c
        for i in range(len(b)):
            r[d+i]-=c*b[i]
        r=_poly_trim(r)
    return _poly_trim(q),_poly_trim(r)

def _poly_eval(p,x):
    s=F(0)
    for c in reversed(p):
        s=s*x+c
    return s

def _sturm_sequence(p):
    seq=[_poly_trim(p),_poly_der(_poly_trim(p))]
    while True:
        _,r=_poly_divrem(seq[-2],seq[-1])
        if len(r)==1 and r[0]==0:
            break
        seq.append([-x for x in r])
    return seq

def _variations(vals):
    signs=[1 if v>0 else -1 for v in vals if v]
    return sum(signs[i]!=signs[i-1] for i in range(1,len(signs)))

def _padd(p,q):
    n=max(len(p),len(q)); out=[F(0)]*n
    for i in range(n):
        out[i]=(p[i] if i<len(p) else 0)+(q[i] if i<len(q) else 0)
    return _poly_trim(out)

def _pscale(p,s):
    return [s*x for x in p]

def _px(p):
    return [F(0)]+list(p)

def _Tpoly(n):
    if n==0: return [F(1)]
    if n==1: return [F(0),F(1)]
    a,b=[F(1)],[F(0),F(1)]
    for _ in range(1,n):
        a,b=b,_padd(_pscale(_px(b),2),_pscale(a,-1))
    return b

def run_rational_witness_sturm():
    ms=[1,3,5,7,9,11,13,15]
    ahat=[F("1.2598224203066"),F("-0.3930260706508"),F("0.2090203393372"),
          F("-0.1250337733856"),F("0.0761080283701"),F("-0.0444368250861"),
          F("0.0231362615839"),F("-0.0089556495026")]
    M=F("1.00000000000006")
    P=[F(0)]
    for a,n in zip(ahat,ms):
        P=_padd(P,_pscale(_Tpoly(n),a))
    # Q=M^2-P^2
    P2=[F(0)]*(2*len(P)-1)
    for i,a in enumerate(P):
        for j,b in enumerate(P):
            P2[i+j]+=a*b
    Q=[-x for x in P2]
    if len(Q)<1: Q=[F(0)]
    Q[0]+=M*M
    S=_sturm_sequence(Q)
    vm=_variations([_poly_eval(q,F(-1)) for q in S])
    vp=_variations([_poly_eval(q,F(1)) for q in S])
    assert vm==vp
    assert _poly_eval(Q,F(-1))>0 and _poly_eval(Q,F(1))>0
    print("PASS_SIGMA002_RATIONAL_STURM_WITNESS")
    print("Sturm root count on [-1,1] =", vm-vp)
    print("certified norm <", float(M))


def run_gaussian_kernel_exact():
    from fractions import Fraction as F
    from math import comb, factorial, isqrt

    # End-to-end exact rational enclosure of the sigma=0.02 Gaussian covariance
    # and degree-15 Bell kernel used by the global optimization certificate.
    SIGMA = F(1,50)
    MS = [1,3,5,7,9,11,13,15]

    class IV:
        def __init__(self, lo, hi=None):
            self.lo=F(lo); self.hi=F(lo if hi is None else hi)
            assert self.lo <= self.hi
        def __add__(self,o):
            o=iv(o); return IV(self.lo+o.lo,self.hi+o.hi)
        __radd__=__add__
        def __neg__(self): return IV(-self.hi,-self.lo)
        def __sub__(self,o): return self+(-iv(o))
        def __rsub__(self,o): return iv(o)-self
        def __mul__(self,o):
            o=iv(o)
            v=[self.lo*o.lo,self.lo*o.hi,self.hi*o.lo,self.hi*o.hi]
            return IV(min(v),max(v))
        __rmul__=__mul__
        def recip(self):
            assert not (self.lo <= 0 <= self.hi)
            a,b=F(1,self.lo),F(1,self.hi)
            return IV(min(a,b),max(a,b))
        def __truediv__(self,o): return self*iv(o).recip()
        def __rtruediv__(self,o): return iv(o)/self
        def __pow__(self,n):
            assert isinstance(n,int) and n>=0
            if n==0: return IV(1)
            if self.lo>=0: return IV(self.lo**n,self.hi**n)
            vals=[self.lo**n,self.hi**n]
            if n%2==0 and self.lo<0<self.hi: vals.append(F(0))
            return IV(min(vals),max(vals))
    def iv(x): return x if isinstance(x,IV) else IV(x)

    def atan_inv_bounds(q,N):
        s=F(0)
        for n in range(N):
            t=F(1,(2*n+1)*q**(2*n+1))
            s += t if n%2==0 else -t
        nxt=F(1,(2*N+1)*q**(2*N+1))
        return (s,s+nxt) if N%2==0 else (s-nxt,s)

    # Machin: pi = 16 atan(1/5) - 4 atan(1/239).
    al,ah=atan_inv_bounds(5,80)
    bl,bh=atan_inv_bounds(239,20)
    PI=IV(16*al-4*bh,16*ah-4*bl)

    def sqrt_iv(x,D=80):
        S=10**D
        n=isqrt((x.lo.numerator*S*S)//x.lo.denominator)
        lo=F(n,S)
        while lo*lo>x.lo: n-=1; lo=F(n,S)
        while F(n+1,S)**2<=x.lo: n+=1; lo=F(n,S)
        m=isqrt((x.hi.numerator*S*S)//x.hi.denominator)
        hi=F(m,S)
        if hi*hi<x.hi: m+=1; hi=F(m,S)
        return IV(lo,hi)

    SQRTPI=sqrt_iv(PI,90)

    # Bernoulli numbers and Taylor coefficients.
    B=[F(0)]*31; B[0]=F(1)
    for m in range(1,31):
        B[m]=-sum(F(comb(m+1,k))*B[k] for k in range(m))/F(m+1)
    def cc(m): # z coth z
        return F(1) if m==0 else F(2**(2*m))*B[2*m]/F(factorial(2*m))
    def ct(m): # z tanh z
        return F(0) if m==0 else F(2**(2*m)*(2**(2*m)-1))*B[2*m]/F(factorial(2*m))

    A=PI/100
    PREF=F(1)/(25*PI)

    def moment(m):
        return SQRTPI*F(factorial(2*m),2*(4**m)*factorial(m))

    def partial(kind,M):
        s=IV(0)
        for m in range(M+1):
            c=cc(m) if kind=="A" else ct(m)
            if c: s += c*(A**(2*m))*moment(m)
        return PREF*s

    # On t<=20 the partial-fraction geometric ratios obey q_coth<=0.04,
    # q_tanh<=0.16, so even M=12 is a lower truncation and odd M=13 upper.
    assert F(20*20,10000) <= F(4,100)
    assert F(4*20*20,10000) <= F(16,100)

    # e^-400 < 1e-160 follows from e>2.7 and 2.7^400>1e160.
    assert F(27,10)**400 > 10**160
    E400=F(1,10**160)
    T=F(20)
    def tail_even(m):
        I=E400/(2*T) # I_0
        p=2
        while p<=2*m:
            I=F(1,2)*T**(p-1)*E400+F(p-1,2)*I
            p+=2
        return I
    def poly_tail(kind,M):
        s=F(0)
        for m in range(M+1):
            c=abs(cc(m) if kind=="A" else ct(m))
            if c: s += c*(A.hi**(2*m))*tail_even(m)
        return PREF.hi*s

    I0=tail_even(0); I1=E400/2
    tailA=PREF.hi*(I0+A.hi*I1) # z coth z <= 1+z
    tailB=PREF.hi*(A.hi*I1)    # z tanh z <= z

    A0=IV(partial("A",12).lo-poly_tail("A",12),
          partial("A",13).hi+poly_tail("A",13)+tailA)
    B0=IV(partial("B",12).lo-poly_tail("B",12),
          partial("B",13).hi+poly_tail("B",13)+tailB)

    def exp_pos_small(x,N=14):
        def s(v):
            term=F(1); sm=F(1)
            for n in range(1,N+1):
                term=term*v/F(n); sm+=term
            nxt=term*v/F(N+1)
            return sm,sm+nxt/(1-v/F(N+2))
        lo,_=s(x.lo); _,hi=s(x.hi)
        return IV(lo,hi)

    X=(PI**2)/10000
    EX=exp_pos_small(X,14)
    BC=(PI*SQRTPI)*EX/F(10**6)
    AC=A0+BC

    def fourth(x): return sqrt_iv(sqrt_iv(x,75),65)
    NUA=sqrt_iv(AC/BC,65)
    NUB=sqrt_iv(A0/B0,65)
    KQ=fourth(A0**3)/fourth(AC*BC*B0)
    KP=fourth(B0*AC*A0)/fourth(BC**3)

    def round_out(x,N):
        S=10**N
        lo=(x.lo.numerator*S)//x.lo.denominator
        hi=(x.hi.numerator*S+x.hi.denominator-1)//x.hi.denominator
        return IV(F(lo,S),F(hi,S))
    NUA=round_out(NUA,32); NUB=round_out(NUB,32)
    KQ=round_out(KQ,32); KP=round_out(KP,32)

    # Exact e^{-x} bounds for x<=12 by integer+unit-interval alternating series.
    def exp_neg_unit(r,N=70):
        s=F(0); term=F(1)
        for n in range(N+1):
            if n: term*=r/F(n)
            s += term if n%2==0 else -term
        nxt=term*r/F(N+1)
        s2=s+(nxt if (N+1)%2==0 else -nxt)
        return min(s,s2),max(s,s2)
    E1=exp_neg_unit(F(1),70)
    def exp_neg_single(x):
        n=x.numerator//x.denominator; r=x-F(n)
        rl,rh=exp_neg_unit(r,70)
        return E1[0]**n*rl,E1[1]**n*rh
    def exp_neg_iv(x):
        l,_=exp_neg_single(x.hi); _,h=exp_neg_single(x.lo)
        return IV(l,h)

    DQ=NUA+NUB-2*KQ
    DP=NUA+NUB-2*KP

    # The tiny positive-frequency "plus" diagonal terms are bounded separately.
    ELOW=sum(F(1,factorial(n)) for n in range(13)) # strict lower bound for e
    def exp_large_upper(n,r):
        sr=sum(r**k/F(factorial(k)) for k in range(9))
        return F(1)/(ELOW**n*sr)
    PLUS_Q=exp_large_upper(141,F(415,1000))
    PLUS_P=exp_large_upper(141,F(38,100))
    assert (PLUS_Q+PLUS_P)/2 < F(4,10**62)

    KD=[]
    for m in MS:
        xq=round_out((PI/F(4))*F(m*m)*DQ,30)
        xp=round_out((PI/F(4))*F(m*m)*DP,30)
        eq,ep=exp_neg_iv(xq),exp_neg_iv(xp)
        KD.append(IV((eq.lo+ep.lo)/2,(eq.hi+ep.hi)/2+F(4,10**62)))

    # Off-diagonal minus branches: exact lower exponents.
    def qminus(m,n,k): return F(m*m)*NUA+F(n*n)*NUB-F(2*m*n)*k
    minq=min(((PI/F(4))*qminus(m,n,KQ)).lo for i,m in enumerate(MS) for j,n in enumerate(MS) if i!=j)
    minp=min(((PI/F(4))*qminus(m,n,KP)).lo for i,m in enumerate(MS) for j,n in enumerate(MS) if i!=j)
    assert minq > F(141415,1000)
    assert minp > F(14152,100)
    UQ=exp_large_upper(141,F(415,1000))
    UP=exp_large_upper(141,F(52,100))
    # Off-diagonal plus branches have exponent >565, hence <1e-240.
    assert F(27,10)**565 > 10**240
    UOFF=(UQ+UP)/2+F(1,10**240)
    assert UOFF < F(37,10**63) # 3.7e-62
    assert UOFF < F(4,10**62)

    # Inclusion in the frozen kernel box used by the exact global replays.
    DLO=[F("0.965861058125584"),F("0.739535853145385"),F("0.458352997987593"),
         F("0.251059553824589"),F("0.128787475201436"),F("0.061358770336711"),
         F("0.026228836249167"),F("0.009843461611360")]
    DHI=[F("0.965861058125585"),F("0.739535853145387"),F("0.458352997987594"),
         F("0.251059553824590"),F("0.128787475201437"),F("0.061358770336712"),
         F("0.026228836249169"),F("0.009843461611361")]
    for i,x in enumerate(KD):
        assert DLO[i] <= x.lo <= x.hi <= DHI[i]

    def dec(x,d=36):
        return f"{float(x):.{d//2}g}" # audit display only

    print("PASS_SIGMA002_GAUSSIAN_TO_DEGREE15_KERNEL_EXACT")
    print("A0 width <", float(A0.hi-A0.lo))
    print("B0 width <", float(B0.hi-B0.lo))
    print("nuA =", float(NUA.lo), float(NUA.hi))
    print("nuB =", float(NUB.lo), float(NUB.hi))
    print("kappa_q =", float(KQ.lo), float(KQ.hi))
    print("kappa_p =", float(KP.lo), float(KP.hi))
    for m,x in zip(MS,KD):
        print("Kdiag",m,float(x.lo),float(x.hi))
    print("offdiag absolute upper <", float(UOFF))
    print("FROZEN_KERNEL_BOX_CONTAINS_END_TO_END_KERNEL = PASS")


def run_local_defect_exact():
    from fractions import Fraction as F
    from math import isqrt

    # Exact rational replay of the local contact-defect shell.
    # Inputs: the previously Krawczyk-isolated contact box and a frozen
    # outward enclosure of the sigma=0.02 Bell kernel.

    ms=[1,3,5,7,9,11,13,15]
    contacts=[
        F("0.31938819100138102995933552928779169"),
        F("0.6201524084605787586273194735355964"),
        F("0.85549611840077681899596911522314974"),
        F("0.98352051035042762467852755195452029"),
    ]
    rad=F(1,10**10)

    def T(n,x):
        if n==0: return F(1)
        if n==1: return x
        a,b=F(1),x
        for _ in range(1,n):
            a,b=b,2*x*b-a
        return b

    def U(n,x):
        if n==0: return F(1)
        if n==1: return 2*x
        a,b=F(1),2*x
        for _ in range(1,n):
            a,b=b,2*x*b-a
        return b

    def eye(n): return [[F(int(i==j)) for j in range(n)] for i in range(n)]
    def tr(A): return [list(row) for row in zip(*A)]
    def mm(A,B):
        return [[sum(A[i][k]*B[k][j] for k in range(len(B)))
                 for j in range(len(B[0]))] for i in range(len(A))]
    def add(A,B): return [[A[i][j]+B[i][j] for j in range(len(A[0]))] for i in range(len(A))]
    def sub(A,B): return [[A[i][j]-B[i][j] for j in range(len(A[0]))] for i in range(len(A))]
    def absm(A): return [[abs(x) for x in row] for row in A]
    def ninf(A): return max(sum(abs(x) for x in row) for row in A)
    def none(A): return max(sum(abs(A[i][j]) for i in range(len(A))) for j in range(len(A[0])))
    def diag(v): return [[v[i] if i==j else F(0) for j in range(len(v))] for i in range(len(v))]
    def adddiag(A,v):
        B=[row[:] for row in A]
        for i in range(len(B)): B[i][i]+=v
        return B

    def inv(A):
        n=len(A)
        X=[list(A[i])+[F(int(i==j)) for j in range(n)] for i in range(n)]
        for c in range(n):
            p=next(r for r in range(c,n) if X[r][c])
            X[c],X[p]=X[p],X[c]
            q=X[c][c]
            X[c]=[z/q for z in X[c]]
            for r in range(n):
                if r==c: continue
                q=X[r][c]
                if q:
                    X[r]=[X[r][j]-q*X[c][j] for j in range(2*n)]
        return [row[n:] for row in X]

    def ldlt_pivots(A):
        n=len(A); L=[[F(0)]*n for _ in range(n)]; D=[F(0)]*n
        for i in range(n): L[i][i]=1
        for j in range(n):
            D[j]=A[j][j]-sum(L[j][k]*L[j][k]*D[k] for k in range(j))
            assert D[j] > 0
            for i in range(j+1,n):
                L[i][j]=(A[i][j]-sum(L[i][k]*L[j][k]*D[k] for k in range(j)))/D[j]
        return D

    # Exact rational center Hermite matrix and derivative-based radius.
    H0=[]; HR=[]
    for y in contacts:
        H0.append([T(n,y) for n in ms])
        HR.append([F(n*n)*rad for n in ms]) # |T_n'| <= n^2
        H0.append([F(n)*U(n-1,y) for n in ms])
        HR.append([F(n*n*(n*n-1),3)*rad if n>1 else F(0) for n in ms])

    H0i=inv(H0)

    # Componentwise Neumann comparison enclosure for H^{-1}.
    Abar=mm(absm(H0i),HR)
    assert ninf(Abar) < 1
    Bcomp=inv(sub(eye(8),Abar))
    Delta=mm(mm(Bcomp,Abar),absm(H0i))
    Habs=add(absm(H0i),Delta)

    # Frozen outward Bell-kernel enclosure.
    dlo=[
     F("0.965861058125584"),F("0.739535853145385"),
     F("0.458352997987593"),F("0.251059553824589"),
     F("0.128787475201436"),F("0.061358770336711"),
     F("0.026228836249167"),F("0.009843461611360")]
    dhi=[
     F("0.965861058125585"),F("0.739535853145387"),
     F("0.458352997987594"),F("0.251059553824590"),
     F("0.128787475201437"),F("0.061358770336712"),
     F("0.026228836249169"),F("0.009843461611361")]
    K0=[[F(0)]*8 for _ in range(8)]
    KR=[[F(0)]*8 for _ in range(8)]
    for i in range(8):
        K0[i][i]=(dlo[i]+dhi[i])/2
        KR[i][i]=(dhi[i]-dlo[i])/2
    for i in range(8):
        for j in range(8):
            if i!=j:
                KR[i][j]=F(4,10**62)

    # Exact center/radius enclosure for M=H^{-T} K H^{-1}.
    M0=mm(tr(H0i),mm(K0,H0i))
    term1=mm(tr(Delta),mm(absm(K0),absm(H0i)))
    term2=mm(tr(absm(H0i)),mm(absm(K0),Delta))
    term3=mm(tr(Delta),mm(absm(K0),Delta))
    termK=mm(tr(Habs),mm(KR,Habs))
    MR=add(add(term1,term2),add(term3,termK))

    ei=[0,2,4,6]; si=[1,3,5,7]
    def block(A,ri,ci): return [[A[i][j] for j in ci] for i in ri]
    Mee0=block(M0,ei,ei); MeeR=block(MR,ei,ei)
    Mes0=block(M0,ei,si); MesR=block(MR,ei,si)
    Mss0=block(M0,si,si); MssR=block(MR,si,si)

    # Exact rational enclosures for C_j=15 sqrt(2/(1-y_j^2)).
    Clo=[F("22.385676350"),F("27.041055090"),F("40.967218209"),F("117.331879836")]
    Chi=[F("22.385676353"),F("27.041055096"),F("40.967218237"),F("117.331880543")]
    for j,y in enumerate(contacts):
        yl,yu=y-rad,y+rad
        assert Clo[j]*Clo[j]*(1-yl*yl) <= 450
        assert Chi[j]*Chi[j]*(1-yu*yu) >= 450
    C0=[(Clo[i]+Chi[i])/2 for i in range(4)]
    CR=[(Chi[i]-Clo[i])/2 for i in range(4)]
    C0m=diag(C0); CRm=diag(CR); Cabsm=diag([C0[i]+CR[i] for i in range(4)])

    lam0=[sum(Mee0[i][j] for j in range(4)) for i in range(4)]
    lamR=[sum(MeeR[i][j] for j in range(4)) for i in range(4)]

    # B = M_es C center/radius.
    B0=mm(Mes0,C0m)
    BR=add(add(mm(MesR,diag([abs(x) for x in C0])),mm(absm(Mes0),CRm)),mm(MesR,CRm))

    # G = 2 diag(lambda) - C M_ss C center/radius.
    CM0C=mm(C0m,mm(Mss0,C0m))
    CMR=add(add(mm(CRm,mm(absm(Mss0),C0m)),mm(C0m,mm(absm(Mss0),CRm))),
            add(mm(CRm,mm(absm(Mss0),CRm)),mm(Cabsm,mm(MssR,Cabsm))))
    G0=[[-CM0C[i][j] for j in range(4)] for i in range(4)]
    for i in range(4): G0[i][i]+=2*lam0[i]
    GR=[row[:] for row in CMR]
    for i in range(4): GR[i][i]+=2*lamR[i]

    mu=F(65,1000); alpha=F(44,100); beta=F(41,100)

    # Uniform G >= mu I.
    rG=ninf(GR)
    ldlt_pivots(adddiag(G0,-(mu+rG)))

    # Uniform ||M_ee||_2 <= alpha.
    rM=ninf(MeeR)
    ldlt_pivots(adddiag([[-Mee0[i][j] for j in range(4)] for i in range(4)],alpha-rM))

    # Uniform ||M_es C||_2 <= beta.
    rBi=ninf(BR); rB1=none(BR)
    # 2.93629e-7 is an outward rational upper bound for sqrt(rBi*rB1).
    rho=F("0.000000293629")
    assert rho*rho >= rBi*rB1
    BtB=mm(tr(B0),B0)
    ldlt_pivots(adddiag([[-BtB[i][j] for j in range(4)] for i in range(4)],(beta-rho)**2))

    # lambda positivity needed in the defect estimate.
    for i in range(4):
        assert 2*(lam0[i]-lamR[i]) >= mu

    # Rational proxy points used by the exterior LP ledger.
    yq=[F("0.319388191001"),F("0.620152408461"),
        F("0.855496118401"),F("0.983520510350")]
    # Markov: ||P'||_inf <= 15^2 for ||P||_inf<=1.
    proxy_error=F(225)*sum(abs(yq[i]-contacts[i])+rad for i in range(4))
    Eproxy=F("0.0057")
    Ecap=F("0.005701")
    assert Eproxy+proxy_error < Ecap

    # Prove -mu + 2 beta sqrt(E) + alpha E < 0 for E<=Ecap.
    sqrtE_up=F("0.07551")
    assert sqrtE_up*sqrtE_up >= Ecap
    assert -mu + 2*beta*sqrtE_up + alpha*Ecap < 0


    # Candidate feasibility: the rational center Q0(z)=P0(sqrt(z))/sqrt(z)
    # stays above 0.99, and the entire contact box is much closer than that margin.
    bvec=[F(1),F(0),F(1),F(0),F(1),F(0),F(1),F(0)]
    astar0=[sum(H0i[i][j]*bvec[j] for j in range(8)) for i in range(8)]
    astarR=[sum(Delta[i][j]*abs(bvec[j]) for j in range(8)) for i in range(8)]

    def padd(p,q):
        n=max(len(p),len(q)); out=[F(0)]*n
        for i in range(n):
            out[i]=(p[i] if i<len(p) else 0)+(q[i] if i<len(q) else 0)
        return out
    def pscale(p,s): return [s*x for x in p]
    def px(p): return [F(0)]+p
    def Tpoly(n):
        if n==0: return [F(1)]
        if n==1: return [F(0),F(1)]
        a,b=[F(1)],[F(0),F(1)]
        for _ in range(1,n):
            a,b=b,padd(pscale(px(b),2),pscale(a,-1))
        return b

    Pc=[F(0)]*16
    for a,n in zip(astar0,ms):
        tp=Tpoly(n)
        for j,c in enumerate(tp): Pc[j]+=a*c
    Q0=[Pc[2*j+1] for j in range(8)]
    Qminus=Q0[:]; Qminus[0]-=F(99,100)

    def trim(p):
        p=list(p)
        while len(p)>1 and p[-1]==0: p.pop()
        return p
    def pder(p): return [F(i)*p[i] for i in range(1,len(p))] or [F(0)]
    def divrem(a,b):
        a=trim(a); b=trim(b); r=a[:]
        q=[F(0)]*max(1,len(a)-len(b)+1)
        while len(r)>=len(b) and not (len(r)==1 and r[0]==0):
            c=r[-1]/b[-1]; d=len(r)-len(b); q[d]+=c
            for i in range(len(b)): r[d+i]-=c*b[i]
            r=trim(r)
        return trim(q),trim(r)
    def sturm(p):
        s=[trim(p),pder(trim(p))]
        while True:
            _,r=divrem(s[-2],s[-1])
            if len(r)==1 and r[0]==0: break
            s.append([-x for x in r])
        return s
    def peval(p,x): return sum(c*x**i for i,c in enumerate(p))
    def variations(vals):
        sg=[1 if v>0 else -1 for v in vals if v]
        return sum(sg[i]!=sg[i-1] for i in range(1,len(sg)))

    SS=sturm(Qminus)
    assert variations([peval(q,F(0)) for q in SS]) == variations([peval(q,F(1)) for q in SS])
    assert peval(Qminus,F(0))>0 and peval(Qminus,F(1))>0
    Qbox_error=sum(F(n*n)*astarR[i] for i,n in enumerate(ms))
    assert Qbox_error < F(1,1000)  # far smaller than the 0.99 margin


    # The exact rational/Sturm witness lies inside the LOCAL proxy shell, so the
    # local stationary maximizer is at least as large as the released witness.
    ahat=[
        F("1.2598224203066"),F("-0.3930260706508"),F("0.2090203393372"),
        F("-0.1250337733856"),F("0.0761080283701"),F("-0.0444368250861"),
        F("0.0231362615839"),F("-0.0089556495026")]
    Mbar=F("1.00000000000006")
    ahat=[a/Mbar for a in ahat]
    def trow_exact(y): return [T(n,y) for n in ms]
    Ewitness=F(4)-sum(sum(ahat[r]*trow_exact(y)[r] for r in range(8)) for y in yq)
    assert Ewitness < Eproxy

    print("PASS_DEGREE15_LOCAL_DEFECT_SHELL_EXACT_REPLAY")
    print("||H0^{-1} R_H||_inf <", float(ninf(Abar)))
    print("mu =",float(mu),"alpha =",float(alpha),"beta =",float(beta))
    print("proxy E error <=",float(proxy_error))
    print("local E cap =",float(Ecap))
    print("candidate Q-box error <=",float(Qbox_error))
    print("rational witness proxy E =",float(Ewitness))
    print("defect coefficient at cap <",
          float(-mu + 2*beta*sqrtE_up + alpha*Ecap))


def run_exterior_exact():
    from fractions import Fraction as F
    import json, hashlib, sys, base64, zlib

    raw = zlib.decompress(base64.b85decode(EMBEDDED_LEDGER_B85.encode("ascii")))
    assert hashlib.sha256(raw).hexdigest() == EMBEDDED_LEDGER_SHA256
    data = json.loads(raw.decode("utf-8"))

    ms = [1,3,5,7,9,11,13,15]
    B = F(31831,25000)  # 1.27324 > 4/pi
    witness = F("2.36461694035383")
    sqrt2_up = F(1414213562373096,10**15)
    offdiag_allowance = F(8,10**61)

    k = [
        F(965861058125584027,10**18),
        F(739535853145386000,10**18),
        F(458352997987593397,10**18),
        F(251059553824589211,10**18),
        F(128787475201436499,10**18),
        F(61358770336711504,10**18),
        F(26228836249167944,10**18),
        F(9843461611360604,10**18),
    ]

    def trow(y):
        T=[F(0)]*16
        T[0]=F(1); T[1]=y
        for n in range(1,15):
            T[n+1]=2*y*T[n]-T[n-1]
        return [T[m] for m in ms]

    ys = [F(j,256) for j in range(257)]
    for s in [
        "0.319388191001","0.451833399296","0.620152408460","0.741273657372",
        "0.855496118401","0.932908520297","0.983520510350","0.9832807762",
        "0.94065","0.4690"
    ]:
        ys.append(F(s))
    ys=sorted(set(ys))

    base_rows=[]
    base_b=[]
    for y in ys:
        r=trow(y)
        base_rows.append(r); base_b.append(F(1))
        base_rows.append([-x for x in r]); base_b.append(F(1))

    # Rational contact-proxy defect cut:
    # E_q >= 0.0057  <=>  sum_j P(y_j^q) <= 3.9943.
    yq=[F("0.319388191001"),F("0.620152408461"),
        F("0.855496118401"),F("0.983520510350")]
    erow=[sum(trow(y)[r] for y in yq) for r in range(8)]
    base_rows.append(erow); base_b.append(F("3.9943"))

    def parse_frac(s):
        if "/" in s:
            a,b=s.split("/")
            return F(int(a),int(b))
        return F(int(s),1)

    def node_rows(l,u):
        rows=list(base_rows)
        b=list(base_b)
        for r in range(8):
            q=[F(0)]*8; q[r]=1
            rows.append(q); b.append(u[r])
            q=[F(0)]*8; q[r]=-1
            rows.append(q); b.append(-l[r])
        return rows,b

    def secant_data(l,u):
        c=[k[r]*(l[r]+u[r]) for r in range(8)]
        const=-sum(k[r]*l[r]*u[r] for r in range(8))
        return c,const

    def verify_prune(l,u,leaf):
        rows,b=node_rows(l,u)
        c,const=secant_data(l,u)
        supp=leaf["support"]
        y=[parse_frac(s) for s in leaf["weights"]]
        assert len(supp)==len(y)
        assert all(v>=0 for v in y)
        for r in range(8):
            assert sum(rows[supp[j]][r]*y[j] for j in range(len(y))) == c[r]
        q_up=const+sum(b[supp[j]]*y[j] for j in range(len(y)))
        B_up=sqrt2_up*q_up+offdiag_allowance
        assert B_up < witness
        # Stored value is only an audit field.
        assert B_up == parse_frac(leaf["value"])
        return B_up

    def verify_empty(l,u,leaf):
        rows,b=node_rows(l,u)
        supp=leaf["support"]
        y=[parse_frac(s) for s in leaf["weights"]]
        assert len(supp)==len(y)
        assert all(v>=0 for v in y)
        assert sum(y)==1
        for r in range(8):
            assert sum(rows[supp[j]][r]*y[j] for j in range(len(y))) == 0
        obj=sum(b[supp[j]]*y[j] for j in range(len(y)))
        assert obj < 0
        assert obj == parse_frac(leaf["value"])
        return obj

    internals=data["internals"]
    leaves=data["leaves"]
    counts={"PRUNE":0,"EMPTY":0}
    worst_prune=F(0)
    closest_empty=None

    def recurse(oid,path,l,u):
        nonlocal worst_prune, closest_empty
        key=f"{oid}:{path}"
        if key in leaves:
            leaf=leaves[key]
            if leaf["type"]=="PRUNE":
                val=verify_prune(l,u,leaf)
                counts["PRUNE"]+=1
                if val>worst_prune: worst_prune=val
            elif leaf["type"]=="EMPTY":
                val=verify_empty(l,u,leaf)
                counts["EMPTY"]+=1
                if closest_empty is None or val>closest_empty: closest_empty=val
            else:
                raise AssertionError("unknown leaf")
            return
        assert key in internals, ("missing node", key)
        r=internals[key]
        mid=(l[r]+u[r])/2
        l0=list(l);u0=list(u);u0[r]=mid
        l1=list(l);u1=list(u);l1[r]=mid
        recurse(oid,path+"0",l0,u0)
        recurse(oid,path+"1",l1,u1)

    sign_patterns=[]
    from itertools import product
    sign_patterns=list(product([-1,1], repeat=7))
    for oid,signs in enumerate(sign_patterns):
        l=[F(0)]*8;u=[F(0)]*8
        l[0]=0;u[0]=B
        for r,s in enumerate(signs,1):
            if s>0:
                l[r]=0;u[r]=B
            else:
                l[r]=-B;u[r]=0
        recurse(oid,"",l,u)

    assert counts=={"PRUNE":368,"EMPTY":33}
    assert len(leaves)==401
    assert len(internals)==273

    print("PASS_DEGREE15_EXTERIOR_EXACT_LEDGER")
    print("PRUNE leaves =",counts["PRUNE"])
    print("EMPTY leaves =",counts["EMPTY"])
    print("internal split nodes =",len(internals))
    print("worst exact PRUNE CHSH upper =",float(worst_prune))
    print("margin below certified witness =",float(witness-worst_prune))
    print("closest exact Farkas slack =",float(closest_empty))
    print("ledger SHA256 =", EMBEDDED_LEDGER_SHA256)

def main():
    run_rational_witness_sturm()
    run_gaussian_kernel_exact()
    run_local_defect_exact()
    run_exterior_exact()
    print("PASS_GITHUB_TEST_01_SIGMA002_END_TO_END")

def test_all_sigma002():
    main()

if __name__ == "__main__":
    main()
